import type { Song, Difficulty, GameVersion } from '@/store/songStore'

// 落雪咖啡屋（lxns.net）中二节奏 API 返回的谱面难度数据结构
interface LxnsSongDifficulty {
  difficulty: number // 0=BASIC, 1=ADVANCED, 2=EXPERT, 3=MASTER, 4=ULTIMA, 5=WORLD'S END
  level: string // 难度标级，如 "14+"；WORLD'S END 恒为 "0"
  level_value: number // 谱面定数；WORLD'S END 恒为 0
  note_designer: string // 谱师
  version: number
  origin_id?: number // 仅 WORLD'S END：原曲 ID
  kanji?: string // 仅 WORLD'S END：谱面属性
  star?: number // 仅 WORLD'S END：谱面星级 1-5
}

interface LxnsSong {
  id: number
  title: string
  artist: string
  genre: string
  bpm: number
  version: number
  disabled?: boolean
  difficulties: LxnsSongDifficulty[]
}

interface LxnsVersion {
  id: number
  title: string
  version: number
}

interface LxnsSongListResponse {
  songs: LxnsSong[]
  genres: unknown[]
  versions: LxnsVersion[]
}

const API_BASE = 'https://maimai.lxns.net/api/v0/chunithm'
const JACKET_BASE = 'https://assets2.lxns.net/chunithm/jacket'

// 难度索引对应关系：0=Basic, 1=Advanced, 2=Expert, 3=Master, 4=ULTIMA, 5=WORLD'S END
const DIFFICULTY_MAP: Record<number, Difficulty> = {
  0: 'BASIC',
  1: 'ADVANCED',
  2: 'EXPERT',
  3: 'MASTER',
  4: 'ULTIMA',
  5: "WORLD'S END",
}

// 解析等级字符串 "13+" -> { level: 13, isPlus: true }
function parseLevel(levelStr: string): { level: number; isPlus: boolean } {
  const isPlus = levelStr.includes('+')
  const cleaned = levelStr.replace('+', '').trim()
  const level = /\d/.test(cleaned) ? parseInt(cleaned, 10) : 0
  return { level: isNaN(level) ? 0 : level, isPlus }
}

// 将 lxns.net API 返回的单首曲目数据转换为应用内部的 Song 格式
function convertLxnsSong(song: LxnsSong): Song[] {
  const result: Song[] = []
  const { id, title, artist, bpm, version: songVersion } = song

  for (const diff of song.difficulties) {
    const difficulty = DIFFICULTY_MAP[diff.difficulty]
    if (!difficulty) continue

    const parsed = parseLevel(diff.level)
    const isWorldsEnd = difficulty === "WORLD'S END"
    // WORLD'S END 没有标级，用谱面星级（1-5）作为等级参与筛选与展示
    const level = parsed.level > 0 ? parsed.level : (diff.star ?? 0)

    result.push({
      id: `${song.id}-${diff.difficulty}`,
      name: title,
      difficulty,
      level,
      isPlus: isWorldsEnd ? false : parsed.isPlus,
      // WORLD'S END 使用原曲曲绘
      cover: `${JACKET_BASE}/${isWorldsEnd ? (diff.origin_id ?? id) : id}.png`,
      author: artist,
      difficultyAuthor: diff.note_designer ?? '',
      bpm,
      genre: song.genre,
      levelValue: diff.level_value > 0 ? diff.level_value : level,
      version: diff.version ?? songVersion,
      star: diff.star,
      kanji: diff.kanji,
    })
  }

  return result
}

export interface FetchMusicResult {
  songs: Song[]
  versions: GameVersion[]
}

// 从 lxns.net API 获取全部中二节奏曲目数据（含版本列表）
export async function fetchMusicData(): Promise<FetchMusicResult> {
  const controller = new AbortController()
  const timeoutId = setTimeout(() => controller.abort(), 15000)

  try {
    const response = await fetch(`${API_BASE}/song/list`, {
      signal: controller.signal,
    })

    if (!response.ok) {
      throw new Error(`获取歌曲数据失败: ${response.status} ${response.statusText}`)
    }

    const data: LxnsSongListResponse = await response.json()

    const allSongs: Song[] = []
    for (const song of data.songs) {
      if (song.disabled) continue
      allSongs.push(...convertLxnsSong(song))
    }

    const versions: GameVersion[] = (data.versions || []).map(v => ({
      version: v.version,
      title: v.title,
    }))

    return { songs: allSongs, versions }
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') {
      throw new Error('获取歌曲数据超时，请检查网络连接')
    }
    throw err
  } finally {
    clearTimeout(timeoutId)
  }
}
