import type { ChuniDifficulty, Difficulty } from '@/store/songStore'

export interface DifficultyTheme {
  value: ChuniDifficulty
  label: string
  short: string
  /** 卡面主色（纯色，用于卡框底色与渐变起点） */
  color: string
  /** 卡面暗色（渐变终点 / 阴影） */
  colorDark: string
  /** 卡面用 CSS background（ULTIMA / WORLD'S END 为特殊纹理或彩虹渐变） */
  surface: string
  /** 筛选按钮渐变（Tailwind 类） */
  gradient: string
  border: string
  shadow: string
  text: string
}

