export function getChuniDifficultyTheme(difficulty: Difficulty): DifficultyTheme {
  return CHUNI_DIFFICULTY_THEME[difficulty as ChuniDifficulty] ?? CHUNI_DIFFICULTY_THEME.BASIC
}

