import { useRef, useState, useEffect, useId, useMemo, memo } from 'react'
import type { Song } from '@/store/songStore'
import { getChuniDifficultyTheme } from '@/lib/chuniDifficulty'

interface ChuniSongCardContentProps {
  song: Song
  className?: string
}

/** 与 .marquee-text 的 padding-right 保持一致（64px = 4rem） */
const MARQUEE_GAP = 64
/** 首字回到左边缘后的停顿时间（秒） */
const MARQUEE_PAUSE = 2

/**
 * 跑马灯：文本超出容器时无缝滚动。
 * 每个实例生成独立 keyframes，使文本滚动到「首字回到左边缘」时停顿 2s 再继续。
 */
function Marquee({ text, className, speed = 70 }: { text: string; className: string; speed?: number }) {
  const containerRef = useRef<HTMLDivElement>(null)
  const textRef = useRef<HTMLParagraphElement>(null)
  const [anim, setAnim] = useState<{ duration: number; pauseFrac: number } | null>(null)
  const uid = useId().replace(/[^a-zA-Z0-9]/g, '')

  useEffect(() => {
    const container = containerRef.current
    const el = textRef.current
    if (!container || !el) return
    // offsetWidth 为布局尺寸（不受父级 transform 缩放影响），减去右侧间距得到纯文本宽度
    const pad = parseFloat(getComputedStyle(el).paddingRight) || 0
    const textWidth = el.offsetWidth - pad
    if (textWidth <= container.clientWidth + 1) {
      setAnim(null)
      return
    }
    // 滚动一份文本（文本宽 + 间距）所需时间，再叠加 2s 停顿
    const scrollTime = (textWidth + MARQUEE_GAP) / speed
    const duration = scrollTime + MARQUEE_PAUSE
    setAnim({ duration, pauseFrac: (MARQUEE_PAUSE / duration) * 100 })
  }, [text, speed])

  const scrolling = anim !== null

  return (
    <div ref={containerRef} className="w-full h-full overflow-hidden flex items-center">
      {scrolling && (
        <style>{`@keyframes marquee-${uid}{0%,${anim!.pauseFrac}%{transform:translateX(0)}100%{transform:translateX(-50%)}}`}</style>
      )}
      <div
        className={scrolling ? 'animate-marquee' : 'flex justify-center w-full'}
        style={
          scrolling
            ? { animationName: `marquee-${uid}`, animationDuration: `${anim!.duration}s` }
            : undefined
        }
      >
        <p ref={textRef} className={`${className}${scrolling ? ' marquee-text' : ''}`}>
          {text}
        </p>
        {scrolling && (
          <p aria-hidden="true" className={`${className} marquee-text`}>
            {text}
          </p>
        )}
      </div>
    </div>
  )
}

function ChuniSongCardContent({ song, className = '' }: ChuniSongCardContentProps) {
  const theme = useMemo(() => getChuniDifficultyTheme(song.difficulty), [song.difficulty])
  const isWorldsEnd = song.difficulty === "WORLD'S END"
  const isUltima = song.difficulty === 'ULTIMA'

  const levelText = song.level > 0 ? String(song.level) : '-'
  const labelFontSize = theme.label.length > 8 ? 20 : theme.label.length > 6 ? 26 : 34
  const starCount = Math.max(0, Math.min(5, song.star ?? 0))
  // 曲名与艺术家之间的分隔线：使用难度主色（WORLD'S END 为彩虹渐变）
  const dividerColor = isWorldsEnd
    ? 'linear-gradient(90deg,#ff2d55,#ff9500,#ffd60a,#34c759,#00c7be,#0a84ff,#bf5af2)'
    : theme.color

  return (
    <div
      className={`relative w-full h-full overflow-hidden rounded-[10px] ${className}`}
      style={{ background: theme.surface }}
    >
      {/* 外描边 */}
      <div className="absolute inset-0 rounded-[10px] ring-2 ring-inset ring-white/80 pointer-events-none z-20" />

      {/* 斜纹装饰（纯色难度） */}
      {!isWorldsEnd && (
        <div
          className="absolute inset-0 opacity-[0.18] pointer-events-none"
          style={{
            backgroundImage:
              'repeating-linear-gradient(135deg, rgba(255,255,255,0.9) 0 2px, transparent 2px 14px)',
          }}
        />
      )}
      {isUltima && (
        <div
          className="absolute inset-0 opacity-70 pointer-events-none"
          style={{
            backgroundImage:
              'repeating-linear-gradient(115deg, rgba(230,0,18,0.85) 0 5px, transparent 5px 26px)',
          }}
        />
      )}

      {/* 曲绘 */}
      <div
        className="absolute rounded-[3px] bg-white p-[5px] shadow-[0_6px_18px_rgba(0,0,0,0.32)]"
        style={{ top: 24, left: 28, right: 28, height: 240 }}
      >
        <img
          src={song.cover}
          alt={song.name}
          className="w-full h-full object-cover rounded-[2px]"
          loading="lazy"
        />
      </div>

      {/* 难度条：WORLD'S END 为全宽蓝渐变条（参照街机卡面）；其余难度为封面下方居中文字 */}
      {isWorldsEnd ? (
        <div
          className="absolute z-10 flex items-center justify-center"
          style={{
            top: 264,
            left: 0,
            right: 0,
            height: 44,
            background: 'linear-gradient(100deg,#22e0ff 0%,#0e8cff 34%,#1550e6 70%,#3a2bd6 100%)',
            boxShadow: 'inset 0 1px 0 rgba(255,255,255,0.45)',
            // 左侧留出等级容器宽度，避免遮挡文字左端
            paddingLeft: 42,
            paddingRight: 8,
          }}
        >
          <span
            className="font-rajdhani font-black leading-none text-white whitespace-nowrap"
            style={{
              fontSize: 26,
              letterSpacing: '0.01em',
              textShadow: '0 1px 0 rgba(0,0,0,0.55), 0 0 8px rgba(0,0,0,0.4)',
            }}
          >
            WORLD'S END
          </span>
        </div>
      ) : (
        <div
          className="absolute z-10 flex items-center justify-center"
          style={{ top: 267, left: 0, right: 0, height: 34 }}
        >
          <span
            className="font-rajdhani font-black leading-none text-white whitespace-nowrap"
            style={{ fontSize: labelFontSize, textShadow: '0 2px 10px rgba(0,0,0,0.55)' }}
          >
            {theme.label}
          </span>
        </div>
      )}

      {/* 等级容器：位于封面左下角，右上四分之一覆盖封面左下区域 */}
      <div
        className="absolute z-20 rounded-[3px] bg-white p-[2px] shadow-[0_6px_16px_rgba(0,0,0,0.42)]"
        style={{ top: 242, left: 12, width: 68, height: 72 }}
      >
        {isWorldsEnd ? (
          <>
            {/* 星级条：深色底 + 金色星（参照街机卡面） */}
            <div
              className="h-[20px] flex items-center justify-center gap-[1px]"
              style={{ background: '#16233f' }}
            >
              {Array.from({ length: starCount || 5 }).map((_, i) => (
                <span key={i} className="text-[12px] leading-none text-amber-400">
                  ★
                </span>
              ))}
            </div>
            {/* 属性汉字：彩虹渐变填充 */}
            <div className="h-[48px] flex items-center justify-center rounded-[1px] bg-white">
              <span
                className="text-[34px] leading-none font-black"
                style={{
                  background: 'linear-gradient(135deg,#ff2d55,#ff9500,#ffd60a,#34c759,#0a84ff,#bf5af2)',
                  WebkitBackgroundClip: 'text',
                  backgroundClip: 'text',
                  color: 'transparent',
                }}
              >
                {song.kanji || '覚'}
              </span>
            </div>
          </>
        ) : (
          <>
            <div className="h-[20px] flex items-center justify-center">
              <span className="text-[10px] font-black tracking-[0.16em] text-[#16233f]">
                LEVEL
              </span>
            </div>
            <div className="relative h-[48px] flex items-center justify-center rounded-[1px] bg-[#16233f]">
              <span className="text-[32px] leading-none font-black text-white">
                {levelText}
              </span>
              {song.isPlus && (
                <span className="absolute right-[5px] top-[2px] text-[15px] leading-none font-black text-white">
                  +
                </span>
              )}
            </div>
          </>
        )}
      </div>

      {/* 白色信息区 */}
      <div className="absolute left-0 right-0 bottom-0 bg-white" style={{ top: 308 }}>
        {/* 曲名 */}
        <div className="absolute left-[14px] right-[14px]" style={{ top: 8, height: 30 }}>
          <Marquee
            text={song.name}
            className="text-[#16233f] text-[20px] leading-none font-black tracking-[0.02em] whitespace-nowrap"
          />
        </div>

        {/* 难度色细横线（分隔曲名与艺术家） */}
        <div
          className="absolute left-[14px] right-[14px] rounded-full"
          style={{ top: 42, height: 2, background: dividerColor }}
        />

        {/* 艺术家 */}
        <div className="absolute left-[14px] right-[14px]" style={{ top: 48, height: 20 }}>
          <Marquee
            text={song.author}
            className="text-[#5b6478] text-[13px] leading-none font-bold whitespace-nowrap"
          />
        </div>

        {/* 定数条（替换原 SCORE 条） */}
        <div
          className="absolute left-0 right-0 bg-[#16233f] flex items-center justify-between px-[16px]"
          style={{ top: 74, height: 32 }}
        >
          <span className="text-[13px] font-black tracking-[0.12em] text-white/85">CONST:</span>
          <span className="text-[18px] leading-none font-black text-white">
            {song.levelValue > 0 ? song.levelValue.toFixed(1) : '—'}
          </span>
        </div>

        {/* 谱师 / BPM */}
        <div
          className="absolute left-0 right-0 bottom-0 flex items-center justify-between gap-3 px-[14px] border-t border-slate-200"
          style={{ height: 40 }}
        >
          <div className="min-w-0 flex-1 flex items-center gap-1.5">
            <span className="text-[9px] font-black tracking-[0.14em] text-[#8a93a6] shrink-0">
              NOTES DESIGNER:
            </span>
            <div className="flex-1 min-w-0 h-[16px]">
              <Marquee
                text={song.difficultyAuthor || '-'}
                speed={60}
                className="text-[12px] font-bold text-[#16233f] whitespace-nowrap"
              />
            </div>
          </div>
          <div className="flex items-baseline gap-1.5 shrink-0">
            <span className="text-[9px] font-black tracking-[0.14em] text-[#8a93a6]">BPM:</span>
            <span className="text-[12px] font-bold text-[#16233f]">{song.bpm}</span>
          </div>
        </div>
      </div>
    </div>
  )
}

export default memo(ChuniSongCardContent)
